window.ScripturaLexicons.BDAG_PART_0144 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikheireo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιχειρέω epikheiréō verbo empreender; tentar; esforçar-se para BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιχειρέω</td><td>verbo</td><td>empreender; tentar; esforçar-se para</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikheiresis-bdag\" data-source=\"BDAG\" data-search=\"ἐπιχείρησις, εως, ἡ epikheírēsis substantivo feminino tentativa; empreendimento; ataque BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιχείρησις, εως, ἡ</td><td>substantivo feminino</td><td>tentativa; empreendimento; ataque</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikheo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιχέω epikhéō verbo; ativo e passivo derramar sobre; aplicar; verter em BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιχέω</td><td>verbo; ativo e passivo</td><td>derramar sobre; aplicar; verter em</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikhoregeo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιχορηγέω epikhorēgéō verbo conceder; fornecer; prover; sustentar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιχορηγέω</td><td>verbo</td><td>conceder; fornecer; prover; sustentar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikhoregia-bdag\" data-source=\"BDAG\" data-search=\"ἐπιχορηγία, ας, ἡ epikhorēgía substantivo feminino auxílio; assistência; sustento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιχορηγία, ας, ἡ</td><td>substantivo feminino</td><td>auxílio; assistência; sustento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikhrio-bdag\" data-source=\"BDAG\" data-search=\"ἐπιχρίω epikhríō verbo ungir; espalhar; aplicar uma substância viscosa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιχρίω</td><td>verbo</td><td>ungir; espalhar; aplicar uma substância viscosa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikhoreo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιχωρέω epikhōréō verbo mover-se para um lado; deslocar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιχωρέω</td><td>verbo</td><td>mover-se para um lado; deslocar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epipsauo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιψαύω epipsaúō verbo tocar; ter contato com; alcançar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιψαύω</td><td>verbo</td><td>tocar; ter contato com; alcançar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eplesa-bdag\" data-source=\"BDAG\" data-search=\"ἔπλησα éplēsa forma verbal; remissão ver πίμπλημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔπλησα</td><td>forma verbal; remissão</td><td>ver πίμπλημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epoikodomeo-bdag\" data-source=\"BDAG\" data-search=\"ἐποικοδομέω epoikodoméō verbo; ativo e passivo construir por cima; edificar sobre; fortalecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐποικοδομέω</td><td>verbo; ativo e passivo</td><td>construir por cima; edificar sobre; fortalecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epokello-bdag\" data-source=\"BDAG\" data-search=\"ἐποκέλλω epokéllō verbo encalhar; fazer encalhar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐποκέλλω</td><td>verbo</td><td>encalhar; fazer encalhar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eponomazo-bdag\" data-source=\"BDAG\" data-search=\"ἐπονομάζω eponomázō verbo; ativo e passivo denominar; chamar; receber um nome BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπονομάζω</td><td>verbo; ativo e passivo</td><td>denominar; chamar; receber um nome</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epopteuo-bdag\" data-source=\"BDAG\" data-search=\"ἐποπτεύω epopteúō verbo observar atentamente; examinar; presenciar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐποπτεύω</td><td>verbo</td><td>observar atentamente; examinar; presenciar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epoptes-bdag\" data-source=\"BDAG\" data-search=\"ἐπόπτης, ου, ὁ epóptēs substantivo masculino observador vigilante; testemunha ocular BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπόπτης, ου, ὁ</td><td>substantivo masculino</td><td>observador vigilante; testemunha ocular</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epos-bdag\" data-source=\"BDAG\" data-search=\"ἔπος, ους, τό épos substantivo neutro palavra; expressão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔπος, ους, τό</td><td>substantivo neutro</td><td>palavra; expressão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epouranios-bdag\" data-source=\"BDAG\" data-search=\"ἐπουράνιος, ον epouránios adjetivo; substantivado celestial; do céu; pertencente aos céus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπουράνιος, ον</td><td>adjetivo; substantivado</td><td>celestial; do céu; pertencente aos céus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eprathen-bdag\" data-source=\"BDAG\" data-search=\"ἐπράθην epráthēn forma verbal; remissão ver πιπράσκω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπράθην</td><td>forma verbal; remissão</td><td>ver πιπράσκω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epresthesan-epristhesan-bdag\" data-source=\"BDAG\" data-search=\"ἐπρήσθησαν, ἐπρίσθησαν eprḗsthēsan, eprísthēsan formas verbais; remissão ver πρίζω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπρήσθησαν, ἐπρίσθησαν</td><td>formas verbais; remissão</td><td>ver πρίζω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hepta-bdag\" data-source=\"BDAG\" data-search=\"ἑπτά heptá numeral cardinal indeclinável sete BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑπτά</td><td>numeral cardinal indeclinável</td><td>sete</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heptakis-bdag\" data-source=\"BDAG\" data-search=\"ἑπτάκις heptákis advérbio sete vezes BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑπτάκις</td><td>advérbio</td><td>sete vezes</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-epikheireo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιχειρέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikheiréō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Imperfeito <span class=\"greek\">ἐπεχείρουν</span>; futuro, segunda pessoa do singular <span class=\"greek\">ἐπιχειρήσεις</span>, TestJob 4:4; primeiro aoristo <span class=\"greek\">ἐπεχείρησα</span> (Homero; Hipócrates, VM 1 e outros; inscrições, papiros, LXX). <b>Pôr mãos à obra, empreender, tentar, esforçar-se por</b>, seguido de infinitivo (Heródoto, Aristófanes e outros; LXX; TestJob 4:4; Fílon; Jos., Ant. 4, 310; 8, 3; Justino; Taciano 21, 2): <span class=\"greek\">ἀνελεῖν</span> <span class=\"greek\">αὐτόν</span>, <i>tentar matá-lo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:29</a>; <span class=\"greek\">ὀνομάζειν</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span>, <i>tentar invocar o nome sobre alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:13</a>. Com acusativo: <b>tentar alguma coisa</b> (a menos que se deva subentender <span class=\"greek\">νοῆσαι</span>), Hs 9, 2, 6.</p>\n<p class=\"entry-text\">Acerca da <b>composição literária</b> (Hipócrates, <i><span class=\"greek\">Περὶ</span> <span class=\"greek\">ἀρχαίης</span> <span class=\"greek\">ἰητρικῆς</span></i>, prólogo: <span class=\"greek\">ὁπόσοι</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἐπεχείρησαν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ἰητρικῆς</span> <span class=\"greek\">λέγειν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">γράφειν</span>; Galeno, <i>Foet. Format.</i>, proêmio; Tessalo de Trales, <i>Cat. Cod. Astr.</i> VIII/3, p. 134: <span class=\"greek\">πολλῶν</span> <span class=\"greek\">ἐπιχειρησάντων</span> … <span class=\"greek\">παραδοῦναι</span>; Políbio 2, 37, 4; 3, 1, 4; 12, 28, 3; Diod. S. 4, 1, 2; Jos., Vi. 40; 338; C. Ap. 2, 222): <span class=\"greek\">ἀνατάξασθαι</span> <span class=\"greek\">διήγησιν</span>, <i>empreender a redação de uma narrativa ordenada</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:1</a>.</p>\n<p class=\"entry-text\">— H. Cadbury, «Commentary on the Preface of Luke», <i>Beginnings</i> I/2 (1922), pp. 489–510; L. Alexander, <i>The Preface to Luke’s Gospel</i> (1993), pp. 109s. — DELG, s.v. <span class=\"greek\">χείρ</span>; M-M.</p></section></article>\n<article id=\"entry-epikheiresis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιχείρησις, εως, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikheírēsis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">χείρ</span>; Heródoto e outros; Jos., Ant. 15, 103; 16, 188.) <b>Ato de pôr a mão em alguma coisa, com implicação de gesto vigoroso: tentativa, empreendimento, ataque.</b> Com <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, <i>contra alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 12:3</a>, códice D.</p></section></article>\n<article id=\"entry-epikheo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιχέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikhéō⟧</span><span class=\"separator\">·</span><span>verbo; ativo e passivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro, segunda e terceira pessoas do singular, <span class=\"greek\">ἐπιχεεῖς</span> e <span class=\"greek\">ἐπιχεεῖ</span> (abreviado <span class=\"greek\">χεεῖ</span> na fonte), LXX; aoristo, terceira pessoa do singular <span class=\"greek\">ἐπέχεεν</span>, LXX. Passivo: primeiro futuro, terceira pessoa do plural <span class=\"greek\">ἐπιχυθήσονται</span>, Jó 36:27; aoristo <span class=\"greek\">ἐπεχύθην</span>, LXX; particípio perfeito <span class=\"greek\">ἐπιχεχυμένος</span>, LXX (ver <span class=\"greek\">χέω</span>; Homero e outros; papiros, LXX; JosAs 4:11 [códices AB, por <span class=\"greek\">περιεχύθη</span>]; Jos., Ant. 2, 343 e outros).</p>\n<p class=\"entry-text\"><b>① Fazer com que um líquido seja derramado ou escorra sobre alguma coisa: derramar sobre, verter sobre, aplicar.</b> Com <span class=\"greek\">τὶ</span>, <i>alguma coisa</i>, óleo e vinho (Hipócrates, Mul. 2, 133, vol. VIII, p. 296, 15 L.; <i>Hippiatr.</i> I 9, 4), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:34</a>.</p>\n<p class=\"entry-text\"><b>② Fazer com que um líquido entre em alguma coisa: verter para dentro.</b> (Platão, Rep. 407d; PGM 13, 12; EpArist 293.) <span class=\"greek\">τὶ</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, <i>verter alguma coisa em um recipiente</i>, Hm 5, 1, 5; aqui no sentido de <i>acrescentar ao conteúdo já existente no recipiente</i>. — M-M.</p></section></article>\n<article id=\"entry-epikhoregeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιχορηγέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikhorēgéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐπεχορήγησα</span>; primeiro futuro passivo <span class=\"greek\">ἐπιχορηγηθήσομαι</span>. Para interpretar os usos deste verbo e de seus cognatos, deve-se considerar o possível pano de fundo cultural greco-romano do <b>serviço público generoso</b>, expresso pela família de palavras <span class=\"greek\">χορηγ</span>-.</p>\n<p class=\"entry-text\"><b>① Transferir alguma coisa como dádiva: dar, conceder, outorgar.</b> (Dionísio de Halicarnasso 1, 42; Diógenes Laércio 5, 67; Fálaris, Ep. 50; Alexandre de Afrodísias, Probl. 1, 81. Nos contratos matrimoniais, <span class=\"greek\">ἐ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">δέοντα</span>, BGU 183, 6; POxy 905, 10; CPR I, 27, 12; cf. Estrabão 11, 14, 16.) Com <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span>, <i>alguma coisa a alguém</i>, Hs 2:5, 7; <span class=\"greek\">σπέρμα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σπείραντι</span>, <i>dar semente ao semeador</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 9:10</a>; <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span>, <i>aquele que vos concede o Espírito</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:5</a>; <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐγκράτειαν</span>, <i>a ele, o domínio próprio</i>, 1 Cl 38:2, final.</p>\n<p class=\"entry-text\">No passivo: <span class=\"greek\">ἐπιχορηγηθήσεται</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">εἴσοδος</span>, <i>ser-vos-á concedida a entrada</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 1:11</a>. Sem acusativo que especifique a dádiva (En 7:3), o verbo passa a significar:</p>\n<p class=\"entry-text\"><b>② Prover (às próprias custas): fornecer, suprir.</b> (SEG XXXIX, 605, 2 [205/204 a.C.?]; Dionísio de Halicarnasso 10, 54.) Extensão figurada de ①: <span class=\"greek\">ἐ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀρετήν</span>, <i>suprir ou acrescentar a virtude</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 1:5</a> (dentro de uma variante da forma retórica <span class=\"greek\">κλῖμαξ</span>, «gradação»).</p>\n<p class=\"entry-text\"><b>③ Proporcionar o necessário ao bem-estar de outrem: sustentar, amparar.</b> (Sir 25:22; En 7:3; Ar. 15, 7; ver <span class=\"greek\">ἐπιχορηγία</span>.) <span class=\"greek\">ὁ</span> <span class=\"greek\">πλούσιος</span> <span class=\"greek\">ἐπιχορηγείτω</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πτωχῷ</span>, <i>que o rico ampare o necessitado</i>, 1 Cl 38:2 (Ar. 15, 7); no passivo: <span class=\"greek\">ὁ</span> <span class=\"greek\">πένης</span> <span class=\"greek\">ἐπιχορηγούμενος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πλουσίου</span>, <i>o pobre, sustentado pelo rico</i>, Hs 2:6.</p>\n<p class=\"entry-text\"><span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁφῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">συνδέσμων</span> <span class=\"greek\">ἐπιχορηγούμενον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">συμβιβαζόμενον</span>, <i>todo o corpo, sustentado e unido por articulações e ligamentos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 2:19</a> (o sentido passivo do verbo simples «ser sustentado, receber ajuda» é amplamente atestado: Ps.-Xenofonte, <i>Respubl. Athen.</i> [«Velho Oligarca»] 1, 13; Políbio 3, 75, 3; 4, 77, 2; 9, 44, 1; Sir 44:6; 3 Mac 6:40). Em Hs 2:5, verbo simples e composto parecem equivalentes, mas o composto pode indicar «ajudar posteriormente», pois ali uma pessoa rica é apresentada como obrigada a socorrer uma pobre. — Danker, <i>Benefactor</i>, pp. 331s.; DELG, s.v. <span class=\"greek\">χορός</span>; M-M; ver o verbete seguinte.</p></section></article>\n<article id=\"entry-epikhoregia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιχορηγία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikhorēgía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b>Assistência, apoio, sustento.</b> (Ver o verbete precedente; SIG 818, 9 [79 d.C.], sobre uma «provisão» retirada das receitas de um templo «para» a reparação de uma fortificação; Teófilo de Antioquia 2, 14 [p. 136, 2]; ver <span class=\"greek\">ἐπιχορηγέω</span> ③.) <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span>, <i>do Espírito</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:19</a>; <span class=\"greek\">ἁφὴ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐ</span>., <i>um ligamento que serve de sustentação</i> (cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 2:19</a>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4:16</a>. — M-M.</p></section></article>\n<article id=\"entry-epikhrio-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιχρίω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikhríō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐπέχρισα</span> (ver <span class=\"greek\">χρίω</span>; Homero e outros; Símaco, Ez 13:10; 22:28; TestSol 18:20). <b>Aplicar substância viscosa: ungir, espalhar ou passar (sobre).</b> (Sorano, p. 75, 7; Galeno, CMG V 9, 1, p. 136, 30; Dioscórides 3, 25; PLeid X VII, 36; cf. Od. 21, 179, acerca de preparar um arco friccionando-o com gordura; Luciano, Hist. Conscrib. 62, sobre inscrição coberta de gesso; Galeno, CMG V 4, 2, p. 246, 20.)</p>\n<p class=\"entry-text\">Com <span class=\"greek\">τὶ</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span>, <i>espalhar alguma coisa sobre algo</i>: <span class=\"greek\">πηλὸν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὀφθαλμούς</span>, <i>passar lama umedecida sobre os olhos do homem</i> = <i>(Jesus) ungiu-lhe os olhos com lama umedecida</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9:6</a> (variante <span class=\"greek\">ἐπέθηκεν</span>; ver <span class=\"greek\">ἐπιτίθημι</span> ①ⓐ<span class=\"greek\">α</span>; cf. SIG 1173, 17 = Deissmann, LO 108 [LAE 135], num relato de cura: <span class=\"greek\">κολλύριον</span> <span class=\"greek\">ἐπιχρεῖσαι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὀφθαλμούς</span>).</p>\n<p class=\"entry-text\">Sem menção àquilo que é aplicado, a tradução habitual é <b>ungir</b>: <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὀφθαλμούς</span>, <i>ungir os olhos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9:11</a> (retomando o procedimento do versículo 6). — Acerca da pedra que fechava o túmulo de Jesus: <span class=\"greek\">ἐπέχρισαν</span> <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">σφραγῖδας</span>, <i>aplicaram sete selos</i>, isto é, cera que recebe uma impressão de selo, GPt 8:33. — M-M.</p></section></article>\n<article id=\"entry-epikhoreo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιχωρέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikhōréō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo, terceira pessoa singular <span class=\"greek\">ἐπεχώρησεν</span>, 2 Mac 12:12 (Sófocles, Tucídides e outros; Políbio, inscrições, papiros e Josefo, com vários sentidos). <b>Mover-se para (um lado), deslocar-se.</b> <span class=\"greek\">ὁ</span> <span class=\"greek\">λίθος</span> <span class=\"greek\">ἐπεχώρεσε</span> (= <span class=\"greek\">ἐπεχώρησεν</span>) <span class=\"greek\">παρὰ</span> <span class=\"greek\">μέρος</span>, <i>a pedra deslocou-se para o lado</i>, GPt 9:37 (quanto às emendas conjecturais, ver <span class=\"greek\">ἀποχωρέω</span> e <span class=\"greek\">ὑποχωρέω</span>).</p></section></article>\n<article id=\"entry-epipsauo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιψαύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epipsaúō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐπιψαύσω</span> (Homero e outros; Diod. S. 3, 28, 3; 17, 20, 6; Heron de Alexandria I, p. 6, 11ss.; Heraclito estoico 44, p. 66, 12). <b>Estabelecer contato com: tocar, pegar, alcançar.</b> Com genitivo <span class=\"greek\">τινός</span>, <i>de alguém</i> (Arriano, Cyneg. 9, 2: <span class=\"greek\">ἀλλήλων</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5:14</a>, códice D. Ver <span class=\"greek\">ἐπιφαύσκω</span>.</p></section></article>\n<article id=\"entry-eplesa-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔπλησα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éplēsa⟧</span><span class=\"separator\">·</span><span>forma verbal; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b>Remissão:</b> <span class=\"greek\">ἔπλησα</span>; ver <span class=\"greek\">πίμπλημι</span>.</p></section></article>\n<article id=\"entry-epoikodomeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐποικοδομέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epoikodoméō⟧</span><span class=\"separator\">·</span><span>verbo; ativo e passivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐποικοδόμησα</span> (sobre a ausência de aumento, ver Mlt-H., p. 191); primeiro aoristo passivo <span class=\"greek\">ἐποικοδομήθην</span> (ver <span class=\"greek\">οἰκοδομέω</span>; Tucídides e outros; inscrições, papiros, Fílon, Josefo). Em nossa literatura ocorre em linguagem figurada.</p>\n<p class=\"entry-text\"><b>① Construir alguma coisa sobre algo já construído: edificar sobre, acrescentar à construção.</b> (Xenofonte; Platão, Leg. 5, p. 736e; inscrições; PGiss 67, 12; Jos., Ant. 12, 253.)</p>\n<p class=\"entry-text\"><b>ⓐ Acerca de pedras incorporadas a uma torre:</b> <span class=\"greek\">ἔμελλε</span> <span class=\"greek\">πάλιν</span> <span class=\"greek\">ἐποικοδομεῖσθαι</span>, <i>a construção estava prestes a ser continuada</i>, Hs 9, 5, 1; cf. Hv 3, 8, 9.</p>\n<p class=\"entry-text\"><b>ⓑ Edificar sobre alguma coisa ou alguém.</b> A respeito dos começos de uma congregação (com <span class=\"greek\">θεμέλιον</span> <span class=\"greek\">τιθέναι</span>, «lançar um fundamento»; cf. Jos., Ant. 11, 79; Fílon, Somn. 2, 8: <span class=\"greek\">θεμελίων</span> <span class=\"greek\">τρόπον</span> … <span class=\"greek\">ἄλλα</span> … <span class=\"greek\">σοφῆς</span> <span class=\"greek\">ἀρχιτέκτονο</span> … <span class=\"greek\">ἐποικοδομῶμεν</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 3:10</a>; cf. versículo 14. <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span>, <i>edificar sobre algo</i> (OGI 483, 117: <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">τοίχους</span> <span class=\"greek\">ἐ</span>.), versículo 12.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἐποικοδομηθέντες</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεμελίῳ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀποστόλων</span>, <i>edificados sobre o fundamento dos apóstolos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2:20</a> (<span class=\"greek\">ἐπί</span> com dativo, como Xen., An. 3, 4, 11); cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 2:5</a>, variante de leitura na acepção ②. Esse sentido conduz naturalmente a:</p>\n<p class=\"entry-text\"><b>② Participar de um processo de desenvolvimento pessoal e comunitário: edificar, fortalecer, construir sobre.</b> Imagem menos acentuada que em ①ⓑ (Epicteto 2, 15, 8), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.32\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:32</a>, variante de leitura. <span class=\"greek\">ἐποικοδομούμενοι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span>, <i>sendo edificados sobre ele</i>, isto é, Cristo (a preposição é explicada pelo precedente <span class=\"greek\">ἐρριζωμένοι</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 2:7</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">ὡς</span> <span class=\"greek\">λίθοι</span> <span class=\"greek\">ζῶντες</span> <span class=\"greek\">ἐποικοδομεῖσθε</span> <span class=\"greek\">οἶκος</span> <span class=\"greek\">πνευματικός</span>, <i>como pedras vivas, deixai-vos edificar sobre ele como casa espiritual</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 2:5</a>, variante (o composto vincula o povo de Deus a Cristo, «a pedra viva», versículo 4). Semelhantemente, Jd 20: <span class=\"greek\">ἐ</span>. (<span class=\"greek\">ἀνοικ</span>., P 72) <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span>, <i>edificai-vos uns aos outros sobre a base da fé</i> (<span class=\"greek\">ἐ</span>. com dativo como Epicteto, loc. cit.; Fílon, Gig. 30; Conf. Lingu. 5). — DELG, s.v. <span class=\"greek\">οἶκος</span>; M-M; TW.</p></section></article>\n<article id=\"entry-epokello-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐποκέλλω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epokéllō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐπώκειλα</span> (Heródoto 6, 16; 7, 182; Tucídides 4, 26, 6; Arriano, Anab. 5, 20, 9, de uma embarcação). <b>Encalhar.</b> <span class=\"greek\">τὴν</span> <span class=\"greek\">ναῦν</span>, <i>o navio</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.41\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:41</a>, variante (por <span class=\"greek\">ἐπέκειλαν</span>; ver <span class=\"greek\">ἐπικέλλω</span>, derivado de <span class=\"greek\">κέλλω</span>, «levar à praia»).</p></section></article>\n<article id=\"entry-eponomazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπονομάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eponomázō⟧</span><span class=\"separator\">·</span><span>verbo; ativo e passivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Aoristo <span class=\"greek\">ἐπωνόμασα</span>, LXX; perfeito, primeira pessoa do plural <span class=\"greek\">ἐπωνομάκαμεν</span> (Atenágoras 16, 3 [Platão, Rep. 269d]); aoristo passivo <span class=\"greek\">ἐπωνομάσθην</span> (Justino). Ver <span class=\"greek\">ὀνομάζω</span>; tragédias, Heródoto e outros; LXX; Jos., Ant. 17, 14. <b>Chamar, denominar, dar nome.</b> No passivo: <span class=\"greek\">σὺ</span> <span class=\"greek\">Ἰουδαῖος</span> <span class=\"greek\">ἐπονομάζῃ</span>, <i>tu te denominas judeu</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:17</a>. O prefixo <span class=\"greek\">ἐπι</span>- não acrescenta um significado particular, como em Máximo de Tiro 39, 4a; 5c; Apiano, Basil. 1 §1; Dionísio de Bizâncio §35; Himério, Or. 48 (= Or. 14), 13; TestJud 1:3. — DELG, s.v. <span class=\"greek\">ὄνομα</span>; M-M; TW.</p></section></article>\n<article id=\"entry-epopteuo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐποπτεύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epopteúō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐπώπτευσα</span> (ver o verbete seguinte e <span class=\"greek\">ὁράω</span>; desde Homero; Símaco, Sl 9:35; 32:13; Jos., C. Ap. 2, 294; Atenágoras 13, 2). <b>Prestar atenção especial: observar, vigiar, contemplar.</b> Com <span class=\"greek\">τὶ</span>, <i>algo</i> (Políbio 5, 69, 6; 31, 15, 10; Heraclito estoico 53, p. 75, 19): <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀναστροφήν</span>, <i>a conduta</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 3:2</a>.</p>\n<p class=\"entry-text\">Em uso absoluto com particípio (as palavras <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">καλῶν</span> <span class=\"greek\">ἔργων</span> devem ser relacionadas a <span class=\"greek\">δοξάσωσιν</span>, segundo B. Weiss, Kühl, H. von Soden, Knopf; diferente interpretação em Wohlenberg, Vrede): <span class=\"greek\">ἐποπτεύοντες</span>, <i>quando observarem (essas obras, subentendidas: <span class=\"greek\">τ</span>. <span class=\"greek\">ἔργα</span>)</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 2:12</a> (ver <span class=\"greek\">ἐκ</span> 3g<span class=\"greek\">β</span>; H. Meecham, ET 65 [1953], pp. 93s.). — DELG, s.v. <span class=\"greek\">ὄπωπα</span>; M-M; TW.</p></section></article>\n<article id=\"entry-epoptes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπόπτης, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epóptēs⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete precedente; Píndaro, Ésquilo e outros; inscrições, papiros [ocasionalmente <span class=\"greek\">ἐφόπτης</span>, por exemplo SIG 1053, 3, séc. I a.C.]; LXX, EpArist; Jos., C. Ap. 2, 187; Just., A II, 12, 6: <span class=\"greek\">θεὸν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">ἐ</span>.).</p>\n<p class=\"entry-text\"><b>① Pessoa que vê ou cuida de alguma coisa, com vigilância minuciosa: observador atento, vigilante.</b> Acerca de Deus (Píndaro, N. 9, 5 e outros; Cornuto 9, p. 9, 20; OGI 666, 25 [Nero]: <span class=\"greek\">τ</span>. <span class=\"greek\">Ἥλιον</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">σωτῆρα</span>; Sb 1323, acerca do deus-sol: <span class=\"greek\">θεῷ</span> <span class=\"greek\">ὑψίστῳ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πάντων</span> <span class=\"greek\">ἐπόπτῃ</span>; PGM 12, 237; Est 5:1a; 2 Mac 3:39; 7:35; 3 Mac 2:21; EpArist 16. Também de imperadores, por exemplo IPerg 381; ver C. Burk, <i>De Chionis Epistulis</i>, dissertação, Giessen [1912], p. 11): <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἀνθρωπίνων</span> <span class=\"greek\">ἔργων</span>, <i>aquele que vigia ou observa atentamente as ações humanas</i>, com a implicação de que nada escapa à percepção de Deus, 1 Cl 59:3 (Diod. S. 16, 49, 5: <span class=\"greek\">τοὺς</span> <span class=\"greek\">θεοὺς</span> <span class=\"greek\">ἐπόπτας</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὅρκων</span>).</p>\n<p class=\"entry-text\"><b>② Pessoa que teve conhecimento direto de alguma coisa, com implicação de privilégio particular: testemunha ocular.</b> Especialmente termo técnico dos mistérios para designar os iniciados no grau máximo (ver SIG 42, 50 [c. 460 a.C.]; 1052, 4: <span class=\"greek\">Ῥοδίων</span> <span class=\"greek\">ἱεροποιοὶ</span> <span class=\"greek\">μύσται</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐπόπται</span> <span class=\"greek\">εὐσεβεῖς</span>; 1053, 3; Michel 1141, 1 [séc. II a.C.]; Plut., Alc. 202 [22, 4]; Himério, Or. [Ecl.] 10, 4; PGM 7, 572), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 1:16</a>. — S. Cole, <i>Theoi Megaloi</i> (1984), pp. 46–48; <i>New Docs</i> 2, p. 87; DELG, s.v. <span class=\"greek\">ὄπωπα</span>; M-M; TW.</p></section></article>\n<article id=\"entry-epos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔπος, ους, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦épos⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero e outros; inscrições, papiros; Sir 44:5.) <b>Palavra.</b> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">εἰπεῖν</span> (Platão e outros; também Fílon e Jos., Ant. 15, 387), expressão que serve para qualificar um discurso que poderia parecer excessivamente categórico: <i>por assim dizer, quase se poderia dizer</i>; ou, talvez, para produzir um clímax: <i>para empregar a palavra exata</i> (quanto a ambas as interpretações, ver os numerosos exemplos no comentário de F. Bleek a Hebreus, ad loc.; ver ainda POxy 67, 14), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:9</a>. — B. 1261s.; DELG; M-M; Sv.</p></section></article>\n<article id=\"entry-epouranios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπουράνιος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epouránios⟧</span><span class=\"separator\">·</span><span>adjetivo; substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">οὐρανός</span>; Homero e outros; Kaibel 261, 10; LXX, pseudoepígrafos; Fílon, Leg. All. 3, 168; Taciano; Atenágoras; Melitão, P. 39, 272.) Em geral, «celestial».</p>\n<p class=\"entry-text\"><b>① Pertencente ao céu, enquanto fenômeno astronômico: celeste, celestial.</b> <span class=\"greek\">σώματα</span> <span class=\"greek\">ἐ</span>. (em oposição a <span class=\"greek\">ἐπίγεια</span>), <i>corpos celestes</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.40\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 15:40</a> (segundo o versículo 41, trata-se do sol, da lua e das estrelas, figuradamente representados como seres vivos revestidos de luz; ver Wendland, <i>Kultur</i>, p. 158).</p>\n<p class=\"entry-text\"><b>② Relativo a um domínio associado a coisas e seres transcendentes: celestial, nos céus.</b></p>\n<p class=\"entry-text\"><b>ⓐ Empregado como adjetivo.</b></p>\n<p class=\"entry-text\"><b><span class=\"greek\">α</span>. Acerca de Deus</b> (Od. 17, 484; Il. 6, 131; Sb 4166: <span class=\"greek\">Ζεὺς</span> <span class=\"greek\">ἐπουράνιος</span> [ver também IK IX–X/2, Nikaia II/1, 1114 e 1115]; Herm. Wr. 434, 9 Sc.; 3 Mac 6:28; 7:6; TestAbr A 2, p. 78, 23 [Stone, p. 4]; GrBar 11:9; SibOr 4, 51, 135; <i>Theosophien</i> 56, 39, p. 182 Erbse [= p. 148, 48 Holladay]): <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ἐ</span>., <i>Pai celestial</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:35</a>, variante de leitura; <span class=\"greek\">δεσπότης</span> <span class=\"greek\">ἐ</span>., <i>Senhor celestial</i>, 1 Cl 61:2.</p>\n<p class=\"entry-text\"><b><span class=\"greek\">β</span>. Acerca de Cristo:</b> <span class=\"greek\">ἐ</span>. (<span class=\"greek\">ἄνθρωπος</span>), <i>homem celestial</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.48\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 15:48</a>s.; <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἀρχιερεὺς</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χ</span>., <i>Jesus Cristo, sumo sacerdote celestial</i>, MPol 14:3.</p>\n<p class=\"entry-text\"><b><span class=\"greek\">γ</span>. Acerca de pessoas e realidades celestiais:</b> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐ</span>. (<span class=\"greek\">ἄνθρωποι</span>), <i>os celestiais (homens)</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.48\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 15:48</a>; <span class=\"greek\">Ἰερουσαλὴμ</span> <span class=\"greek\">ἐ</span>., <i>Jerusalém celestial</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:22</a> (TestSol C, prólogo 2: <span class=\"greek\">Σιών</span>; quanto à ideia, ver <span class=\"greek\">πόλις</span> ②); <span class=\"greek\">βασιλεία</span> <span class=\"greek\">ἐ</span>., <i>reino celestial</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 4:18</a>; EpilMosq 5 (Atenágoras 18, 1); MPol 20:2, variante; (<span class=\"greek\">πατρὶς</span>) <span class=\"greek\">ἐ</span>., <i>pátria celestial</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:16</a>; <span class=\"greek\">ζωὴ</span> <span class=\"greek\">ἐ</span>., <i>vida celestial</i>, 2 Cl 20:5 (cf. Atenágoras 31, 3: <span class=\"greek\">βίον</span>); <span class=\"greek\">κλῆσις</span> <span class=\"greek\">ἐ</span>., <i>vocação celestial</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:1</a>; <span class=\"greek\">δωρεὰ</span> <span class=\"greek\">ἐ</span>., <i>dom celestial</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:4</a>.</p>\n<p class=\"entry-text\"><b>ⓑ Empregado como substantivo, acerca de coisas ou entidades.</b></p>\n<p class=\"entry-text\"><b><span class=\"greek\">α</span>. Neutro plural: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπουράνια</span>.</b> (Acerca de coisas existentes no céu: Platão, Ap. 19b; Sexto Empírico, Astrol. 44; ApcSed 7:2.)</p>\n<p class=\"entry-text\"><b>א. Como perífrase para «céu»:</b> <span class=\"greek\">καθίσας</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐ</span>., <i>assentando-o nos céus</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:20</a>; cf. 2:6; <span class=\"greek\">ἐξουσίαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐ</span>., <i>os poderes celestiais de seres angélicos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 3:10</a>. Como existe mais de um céu (cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 12:2</a>), <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐ</span>. pode designar a habitação de espíritos malignos, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6:12</a>. Mesmo <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:3</a>, <span class=\"greek\">ὁ</span> <span class=\"greek\">εὐλογήσας</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐ</span>., conforme o uso de Efésios, deve ser entendido localmente, <i>nos céus</i> (ver R. Pope, ET 23 [1912], pp. 365–368). — A. Lincoln, NTS 19 (1973), pp. 467–483.</p>\n<p class=\"entry-text\"><b>ב. As coisas celestiais</b> (Fílon, Gig. 62; TestJob 36:3; 38:5), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3:12</a> (ver <span class=\"greek\">ἐπίγειος</span> ②ⓐ); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:5</a>; 9:23; <i>bens celestiais</i>: <span class=\"greek\">αἰτεῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐ</span>., <i>pedir as coisas celestiais</i>, Agr 10; <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">γράψαι</span>, <i>escrever sobre as coisas celestiais</i>, ITr 5:1; <span class=\"greek\">νοεῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐ</span>., <i>entender as coisas celestiais</i>, ITr 5:2. <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span>, <i>todas as coisas</i>, divididas em <span class=\"greek\">ἐ</span>. e <span class=\"greek\">ἐπίγεια</span>, Pol 2:1; entidades celestiais, ISm 6:1 (cf. TestAbr A 4, p. 81, 15 [Stone, p. 10]: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">πνεύματα</span>).</p>\n<p class=\"entry-text\"><b><span class=\"greek\">β</span>. Masculino plural: <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐπουράνιοι</span>.</b> Como designação dos deuses (Teócrito 25, 5; Mosco 2, 21; Luciano, Dial. Deor. 4, 3; TestSol 6:10 [espíritos hostis]): <b>seres celestiais</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:10</a> (ver <span class=\"greek\">ἐπίγειος</span> ①ⓑ<span class=\"greek\">β</span>); ITr 9:1; IEph 13:2. — DELG, s.v. <span class=\"greek\">οὐρανός</span>; <i>New Docs</i> 4, p. 149; EDNT; M-M; TW.</p></section></article>\n<article id=\"entry-eprathen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπράθην</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epráthēn⟧</span><span class=\"separator\">·</span><span>forma verbal; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b>Remissão:</b> <span class=\"greek\">ἐπράθην</span>; ver <span class=\"greek\">πιπράσκω</span>.</p></section></article>\n<article id=\"entry-epresthesan-epristhesan-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπρήσθησαν, ἐπρίσθησαν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eprḗsthēsan, eprísthēsan⟧</span><span class=\"separator\">·</span><span>formas verbais; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b>Remissão:</b> <span class=\"greek\">ἐπρήσθησαν</span>, <span class=\"greek\">ἐπρίσθησαν</span>; ver <span class=\"greek\">πρίζω</span>.</p></section></article>\n<article id=\"entry-hepta-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑπτά</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heptá⟧</span><span class=\"separator\">·</span><span>numeral cardinal indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Numeral indeclinável (desde Homero; empréstimo no hebraico rabínico): <b>sete</b>. Na datação de um acontecimento, MPol 21.</p>\n<p class=\"entry-text\">Como <b>número sagrado</b> (W. Roscher, <i>D. Sieben-u. Neunzahl in Kultus u. Mythus der Griechen</i> [1904]; J. Graf, <i>D. Zahl «Sieben»</i> [1917]; J. Hehn, «Z. Bed. der Siebenzahl», <i>Marti Festschr.</i> [= Beih. ZAW 41, 1925], pp. 128–136; R. Gordis, JBL 62 [1943], pp. 17–26; Jos., Bell. 7, 149: <span class=\"greek\">παρὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Ἰουδαίοις</span> <span class=\"greek\">ἑβδομάδος</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">τιμή</span>, «a estima da hebdômada entre os judeus»), talvez, por vezes, seja determinante na escolha do numeral (Platão, Theaet. 174e: <span class=\"greek\">τὶς</span> <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">πάππους</span> <span class=\"greek\">πλουσίους</span> <span class=\"greek\">ἔχων</span>, «alguém que possui sete avós ricos»; Diod. S. 4, 27, 2: <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">θυγατέρας</span>, «sete filhas»; 4, 61, 3s.).</p>\n<p class=\"entry-text\"><b>Sete espíritos:</b> <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:45</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 16:9</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:2</a>; 11:26. <b>Sete pães:</b> <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:34</a>, 36s.; 16:10; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:5</a>s., 20. <b>Sete cestos:</b> <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:37</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:8</a>. <b>Sete irmãos:</b> <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:25</a>s., 28; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12:20</a>, 22s.; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20:29</a>, 31, 33. <b>Sete filhos:</b> <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:14</a>. <b>Sete nações:</b> <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:19</a> (Dt 7:1). <b>Sete anos:</b> <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:36</a>. <b>Sete dias:</b> <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:6</a>; 21:4, 27; 28:14; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.30\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:30</a>.</p>\n<p class=\"entry-text\"><b>Sete encarregados da comunidade</b> (P. Gaechter, <i>Petrus u. seine Zeit</i> [1958], pp. 106–135), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 6:3</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:8</a>, em que <span class=\"greek\">οἱ</span> <span class=\"greek\">ἑπτά</span>, «os sete», correspondente a <span class=\"greek\">οἱ</span> <span class=\"greek\">δώδεκα</span>, «os doze», designa um grupo definido e fixo (quanto a <span class=\"greek\">οἱ</span> <span class=\"greek\">ἑπτά</span>, «os sete sábios», ver Diógenes Laércio 1, 40, 82; e «os sete contra Tebas», Ésquilo; Diod. S. 4, 64, 1; 4, 66, 1).</p>\n<p class=\"entry-text\"><b>Especialmente no Apocalipse:</b> sete <b>igrejas</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:4</a>, 11, 20; <b>candelabros</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:12</a>, 13 (variante de leitura), 20; 2:1; <b>estrelas</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:16</a>, 20; 2:1; 3:1; <b>tochas</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 4:5</a>; <b>chifres e olhos</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 5:6</a>; <b>selos</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 5:1</a>; 6:1 (cf. GPt 8:33); <b>anjos</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 8:2</a>, 6; 15:1, 6–8; 17:1; 21:9 (cf. En 20:8); <b>trombetas</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 8:2</a>, 6; <b>trovões</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 10:3</a>s.; <b>cabeças</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 12:3</a>; 13:1; 17:3, 7, 9; <b>coroas</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 12:3</a>; <b>taças</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 15:7</a>; 16:1; 17:1; 21:9; <b>governantes</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 17:9</a>; cf. versículo 11; <b>pragas</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 15:1</a>, 6, 8; 21:9; 22:18 (variante); <b>montes</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 17:9</a> (En 18:6; 24:2).</p>\n<p class=\"entry-text\"><b>Sete virtudes:</b> Hv 3, 8, 2 e outros. <span class=\"greek\">χιλιάδες</span> <span class=\"greek\">ἑ</span>., <i>sete mil</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 11:13</a>. Acerca de <span class=\"greek\">ἑβδομηκοντάκις</span> <span class=\"greek\">ἑπτά</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:22</a>, ver <span class=\"greek\">ἑβδομηκοντάκις</span>. — BHHW III, p. 1785. Sobre <span class=\"greek\">ἕβδομας</span>, ver o verbete correspondente; cf. <span class=\"greek\">ζ</span>´. — DELG; M-M; EDNT; TW.</p></section></article>\n<article id=\"entry-heptakis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑπτάκις</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heptákis⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Advérbio (Píndaro, Aristófanes e outros; SIG 1068, 8 [Patmos, séculos III–II a.C.]: <span class=\"greek\">ἑπτάκι</span>; IG V/I, 213, 16 [século V a.C.]: <span class=\"greek\">ἑπτάκιν</span>; PGM 4, 1272; 1, 143 [<span class=\"greek\">ἑπτάκις</span> <span class=\"greek\">ἑπτά</span>]; LXX; EpArist 177; Fílon, Op. M. 91; Jos., Ant. 3, 242). <b>Sete vezes</b> (como número relativamente elevado; cf. Diod. S. 4, 16, 2, sobre a valorosa amazona vitoriosa sete vezes), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:4</a>b; 1 Cl 5:6.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἕως</span> <span class=\"greek\">ἑ</span>., <i>até sete vezes</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:21</a>s.; <span class=\"greek\">ἑ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡμέρας</span>, <i>sete vezes por dia</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:4</a>a (cf. Luciano, Jupp. Trag. 49: <span class=\"greek\">πεντάκις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡμ</span>.; Jos., Ant. 3, 199: <span class=\"greek\">δὶς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡμ</span>.; Horápolo 1, 8, p. 9: <span class=\"greek\">τριακοντάκις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡ</span>.). — <i>New Docs</i> 4, p. 149; M-M; TW.</p></section></article>"};
